# --- font engine: each glyph is (advance, width, height, top, b64) where
# top is the bitmap top row relative to the baseline (negative = above),
# and b64 packs 4 pixels per byte at 2 bits per pixel (0 = paper, 3 = ink).
def _glyph(font, ch):
    g = font.get(ch)
    if g is None:
        g = font.get(" ")
    return g

def _blit(font, ch, x, base_y, color):
    g = _glyph(font, ch)
    if g is None:
        return 0
    adv, w, h, top, b64 = g
    if w == 0 or h == 0:
        return adv
    data = base64.b64decode(b64)
    r0, g0, b0 = color
    for row in range(h):
        yy = base_y + top + row
        if yy < 0 or yy >= H:
            continue
        for col in range(w):
            i = row * w + col
            lv = (data[i >> 2] >> (2 * (i & 3))) & 3
            if lv == 0:
                continue
            xx = x + col
            if xx < 0 or xx >= W:
                continue
            k = (yy * W + xx) * 3
            if lv == 3:
                buf[k] = r0
                buf[k + 1] = g0
                buf[k + 2] = b0
            else:
                buf[k] = (r0 * lv + buf[k] * (3 - lv)) // 3
                buf[k + 1] = (g0 * lv + buf[k + 1] * (3 - lv)) // 3
                buf[k + 2] = (b0 * lv + buf[k + 2] * (3 - lv)) // 3
    return adv

def text(font, s, x, base_y, color):
    cx = x
    for ch in s:
        cx += _blit(font, ch, cx, base_y, color)
    return cx

def text_w(font, s):
    return sum((_glyph(font, ch) or (0, 0, 0, 0, ""))[0] for ch in s)

def centre(font, s, base_y, color):
    text(font, s, (W - text_w(font, s)) // 2, base_y, color)

def wrap(font, s, width):
    lines, cur = [], ""
    for word in s.split(" "):
        t = word if not cur else cur + " " + word
        if text_w(font, t) <= width:
            cur = t
        else:
            if cur:
                lines.append(cur)
            # hard-split a single over-wide word
            while text_w(font, word) > width and len(word) > 1:
                n = 1
                while n < len(word) and text_w(font, word[:n + 1]) <= width:
                    n += 1
                lines.append(word[:n])
                word = word[n:]
            cur = word
    if cur:
        lines.append(cur)
    return lines

def para(font, s, x, base_y, width, color, lh):
    y = base_y
    for line in wrap(font, s, width):
        text(font, line, x, y, color)
        y += lh
    return y

# --- pixel buffer and shapes ---
buf = bytearray(W * H * 3)

def px(x, y, c):
    if 0 <= x < W and 0 <= y < H:
        i = (y * W + x) * 3
        buf[i:i + 3] = bytes(c)

def rect(x, y, w, h, c):
    x0, y0 = max(0, x), max(0, y)
    x1, y1 = min(W, x + w), min(H, y + h)
    if x1 <= x0 or y1 <= y0:
        return
    row = bytes(c) * (x1 - x0)
    for yy in range(y0, y1):
        base = (yy * W + x0) * 3
        buf[base:base + len(row)] = row

def hline(x, y, w, c):
    rect(x, y, w, 1, c)

def vline(x, y, h, c):
    rect(x, y, 1, h, c)

def circle(cx, cy, r, c, fill=True):
    for yy in range(cy - r, cy + r + 1):
        for xx in range(cx - r, cx + r + 1):
            d2 = (xx - cx) ** 2 + (yy - cy) ** 2
            if fill:
                if d2 <= r * r:
                    px(xx, yy, c)
            else:
                if r * r - 2 * r <= d2 <= r * r:
                    px(xx, yy, c)

def line(x0, y0, x1, y1, c, w=1):
    dx = abs(x1 - x0)
    dy = -abs(y1 - y0)
    sx = 1 if x0 < x1 else -1
    sy = 1 if y0 < y1 else -1
    err = dx + dy
    x, y = x0, y0
    while True:
        if w <= 1:
            px(x, y, c)
        else:
            rect(x - w // 2, y - w // 2, w, w, c)
        if x == x1 and y == y1:
            break
        e2 = 2 * err
        if e2 >= dy:
            err += dy
            x += sx
        if e2 <= dx:
            err += dx
            y += sy

def tri(x1, y1, x2, y2, x3, y3, c):
    ys = sorted([(x1, y1), (x2, y2), (x3, y3)], key=lambda p: p[1])
    (ax, ay), (bx, by), (cx, cy) = ys

    def edge(xa, ya, xb, yb, y):
        if yb == ya:
            return xa
        return xa + (xb - xa) * (y - ya) / (yb - ya)
    for y in range(ay, cy + 1):
        if y < by:
            xa = edge(ax, ay, bx, by, y)
            xb = edge(ax, ay, cx, cy, y)
        else:
            xa = edge(bx, by, cx, cy, y)
            xb = edge(ax, ay, cx, cy, y)
        x0, x1 = int(min(xa, xb)), int(max(xa, xb))
        hline(x0, y, x1 - x0 + 1, c)

def poly(points, c):
    # filled polygon by scanlines; points = [(x, y), ...] in order
    if len(points) < 3:
        return
    ys = [p[1] for p in points]
    for y in range(min(ys), max(ys) + 1):
        xs = []
        n = len(points)
        for i in range(n):
            x1, y1 = points[i]
            x2, y2 = points[(i + 1) % n]
            if (y1 <= y < y2) or (y2 <= y < y1):
                xs.append(x1 + (x2 - x1) * (y - y1) / (y2 - y1))
        xs.sort()
        for i in range(0, len(xs) - 1, 2):
            hline(int(xs[i]), y, int(xs[i + 1]) - int(xs[i]) + 1, c)

def disc_num(cx, cy, r, n, bg, fg=(), f=None, dy=5):
    circle(cx, cy, r, bg)
    s = str(n)
    f = f or FONT_BODYS2
    text(f, s, cx - text_w(f, s) // 2, cy + dy, fg or (255, 255, 255))

