# --- small flag helpers ---
def bands3(x, y, w, h, cols):
    for i, c in enumerate(cols):
        rect(x, y + i * h // 3, w, h // 3 + 1, c)

def stripes(x, y, w, h, c1, c2, n=7):
    for i in range(n):
        rect(x, y + i * h // n, w, h // n + 1, c1 if i % 2 == 0 else c2)

def caption(x, y, w, s):
    rect(x, y, w, 13, NAVY)
    text(FONT_BODYS3, s, x + 6, y + 10, WHITE)

# --- big illustrations (235 x 91) ---
def scene_summit(x, y, w, h):
    rect(x, y, w, h, (232, 214, 176))
    rect(x, y, w, 14, (196, 164, 120))
    # three flags on poles above the table
    fx = [x + 22, x + 96, x + 170]
    stripes(fx[0], y + 18, 46, 26, (178, 34, 52), WHITE)
    rect(fx[0], y + 18, 20, 13, NAVY)
    for dx in (4, 10, 16):
        for dy in (3, 8):
            circle(fx[0] + dx, y + 18 + dy, 1, WHITE)
    rect(fx[1], y + 18, 46, 26, (222, 41, 16))
    circle(fx[1] + 11, y + 31, 4, GOLD)
    for dx, dy in ((22, 22), (28, 25), (28, 31), (22, 34), (17, 28)):
        circle(fx[1] + dx, y + dy, 1, GOLD)
    bands3(fx[2], y + 18, 46, 26, (WHITE, (0, 57, 166), (213, 0, 50)))
    for px0 in fx:
        vline(px0 + 23, y + 18, 44, (90, 70, 50))
    # table and three seated figures
    rect(x, y + 62, w, h - 62, (122, 82, 52))
    rect(x, y + 62, w, 4, (90, 58, 34))
    for cx0 in (x + 45, x + 117, x + 190):
        circle(cx0, y + 52, 10, (226, 190, 160))
        poly([(cx0 - 18, y + 78), (cx0 + 18, y + 78),
              (cx0 + 10, y + 60), (cx0 - 10, y + 60)], (52, 52, 52))
    caption(x, y + h - 13, w, "SHENZHEN - FIRST TRILATERAL SUMMIT")

def scene_gta(x, y, w, h):
    for i, c in enumerate([(124, 58, 120), (186, 92, 60), (232, 140, 70),
                           (240, 180, 90), (250, 214, 130)]):
        rect(x, y + i * (h - 13) // 5, w, (h - 13) // 5 + 1, c)
    for sx0, sy0 in ((x + 20, y + 8), (x + 210, y + 14), (x + 120, y + 5),
                     (x + 60, y + 20), (x + 180, y + 26)):
        circle(sx0, sy0, 1, WHITE)
    # skyline with lit windows
    base = y + h - 13
    bx = x
    for bw, bh in ((34, 26), (26, 40), (40, 22), (30, 48), (36, 30),
                   (28, 44), (34, 24), (30, 36)):
        rect(bx, base - bh, bw, bh, (38, 28, 52))
        for wy in range(base - bh + 5, base - 4, 9):
            for wx in range(bx + 5, bx + bw - 4, 9):
                if (wx * 7 + wy * 3) % 11 < 4:
                    px(wx, wy, (255, 214, 110))
                    px(wx + 1, wy, (255, 214, 110))
        bx += bw + 2
    # big VI
    line(x + 88, y + 22, x + 106, y + 62, WHITE, 7)
    line(x + 124, y + 22, x + 106, y + 62, WHITE, 7)
    rect(x + 134, y + 22, 8, 40, WHITE)
    caption(x, y + h - 13, w, "VICE CITY - MIDNIGHT WORLDWIDE")

def scene_ipo(x, y, w, h):
    rect(x, y, w, h, (16, 28, 54))
    # candlesticks
    cx = x + 18
    for i, (up, ch) in enumerate(((1, 26), (1, 34), (0, 20), (1, 40), (1, 46))):
        col = (46, 180, 90) if up else (220, 70, 60)
        top = y + 58 - ch
        vline(cx + 5, top - 6, ch + 12, col)
        rect(cx, top, 11, ch, col)
        cx += 26
    line(x + 14, y + 62, x + 150, y + 22, GOLD, 2)
    line(x + 150, y + 22, x + 168, y + 30, GOLD, 2)
    text(FONT_KICK, "$107.3BN", x + 148, y + 16, GOLD)
    caption(x, y + h - 13, w, "NASDAQ - ANT - RECORD DEBUT")

def scene_hormuz(x, y, w, h):
    rect(x, y, w, h - 34, (214, 228, 232))
    rect(x, y + h - 47, w, 34, (36, 98, 140))
    rect(x, y + h - 47, w, 3, (20, 70, 110))
    # tanker: hull, containers, bridge tower
    rect(x + 18, y + 52, 150, 16, (40, 40, 44))
    tri(x + 168, y + 52, x + 186, y + 58, x + 168, y + 68, (40, 40, 44))
    for i, c in enumerate([(178, 34, 52), (232, 140, 70), (46, 125, 60),
                           (43, 93, 168)]):
        rect(x + 26 + i * 30, y + 36, 26, 16, c)
    rect(x + 146, y + 28, 16, 24, WHITE)
    rect(x + 150, y + 32, 8, 4, NAVY)
    # mine with spikes, dashed route
    for mx0 in range(x + 30, x + 200, 14):
        px(mx0, y + 74, (255, 255, 255))
    circle(x + 198, y + 70, 6, (30, 30, 30))
    for ang in range(0, 360, 45):
        import math
        dx = int(9 * math.cos(math.radians(ang)))
        dy = int(9 * math.sin(math.radians(ang)))
        line(x + 198, y + 70, x + 198 + dx, y + 70 + dy, (30, 30, 30), 1)
    tri(x + 198, y + 56, x + 202, y + 64, x + 194, y + 64, (232, 140, 70))
    caption(x, y + h - 13, w, "HORMUZ - CLAIM UNVERIFIED")

