def draw_map(x0, y0, w, h):
    rect(x0, y0, w, h, SEA)
    def conv(lon, lat):
        return (int(x0 + (lon + 170) / 360.0 * w),
                int(y0 + (72 - lat) / 130.0 * h))
    for cont in CONTINENTS:
        poly([conv(lon, lat) for lon, lat in cont], LAND)
    for num, lon, lat, region, dx, dy in PINS:
        px0, py0 = conv(lon, lat)
        if dx or dy:
            circle(px0, py0, 3, REG[region])
            line(px0, py0, px0 + dx, py0 + dy, REG[region], 1)
            disc_num(px0 + dx, py0 + dy, 7, num, REG[region],
                     f=FONT_BODYS3, dy=4)
        else:
            disc_num(px0, py0, 7, num, REG[region], f=FONT_BODYS3, dy=4)

def draw_legend(x, y):
    items = [("Europe", REG["Europe"]), ("Middle East", REG["Middle East"]),
             ("Asia", REG["Asia"]), ("Americas", REG["Americas"]),
             ("Africa", REG["Africa"]), ("Oceania", REG["Oceania"])]
    cx = x
    for i, (label, col) in enumerate(items):
        if i == 3:
            cx = x
            y += 13
        circle(cx + 4, y - 4, 4, col)
        text(FONT_BODYS2, label, cx + 11, y, INK)
        cx += 11 + text_w(FONT_BODYS2, label) + 14

